from pathlib import Path
import base64
import sys
p=Path(sys.argv[1] if len(sys.argv)>1 else 'app/KB911.html')
s=p.read_text(encoding='utf-8')

def rep(a,b,n=1):
    global s
    if a not in s: raise SystemExit('patch_v4 missing fragment: '+a[:100])
    s=s.replace(a,b,n)

# A3 landscape by default and primary image-load button.
rep('<button id="btnImage">Загрузить картинку</button>','<button id="btnImage" class="primary">Загрузить картинку</button>')
rep('<button data-tool="text">Добавить надпись</button>','<button data-tool="text">Добавить надпись</button>\n  <button data-tool="leader">Сноска</button>')
rep('<select id="paperSize"><option selected>A4</option><option>A3</option>','<select id="paperSize"><option>A4</option><option selected>A3</option>')

# Donation is its own module below the frame description; handshake instead of heart.
old='<div id="donateWrap"><button id="donateBtn">♥ Попрошайка ▾</button><div id="donateMenu"><button type="button">Варианты поддержки добавим позже</button></div></div>\n    <div class="hint">Контур 0,3 мм, отступ от края листа 5 мм. Название и логотип можно включать независимо.</div>'
new='<div class="hint">Контур 0,3 мм, отступ от края листа 5 мм. Название и логотип можно включать независимо.</div>\n  </div>\n  <div class="group" id="donateModule"><div id="donateWrap"><button id="donateBtn" type="button" aria-expanded="false"><img src="__KB911_DONATE_ICON__" alt="">Попрошайка ▾</button><div id="donateMenu">Если Вам понравилось что я сделал, если Вам действительно помогает в работе эта бесплатная утилита, буду благодарен любой сумме в качестве безвозмездной помощи ))) советы и пожелания по улучшению готов принять по электронной почте (можно скопировать нажав на название программы), СПАСИБО за Ваше участие!</div><div id="donateQrArea"><img id="donateQrImage" src="__KB911_DONATE_QR__" alt="QR-код для перевода через Т-Банк или Сбербанк"></div></div>'
rep(old,new)
for placeholder, path in [('__KB911_DONATE_ICON__',Path('assets/donate_icon.png')),('__KB911_DONATE_QR__',Path('assets/donate_qr.png'))]:
    if s.count(placeholder)!=1: raise SystemExit('donation image placeholder missing: '+placeholder)
    s=s.replace(placeholder,'data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode('ascii'),1)
# close donate module before aside closes
rep('  </div>\n</aside>\n</main>','  </div>\n</aside>\n</main>',1)

# Text settings: italic + border.
rep('<div class="tp-full tp-checks"><label><input id="textBold" type="checkbox" checked> Жирный</label></div>','<div class="tp-full tp-checks"><label><input id="textBold" type="checkbox" checked> Жирный</label><label><input id="textItalic" type="checkbox"> Курсив</label><label><input id="textBorder" type="checkbox"> Обводка поля</label></div>')
rep("const builtText={font:'Bahnschrift',fontSize:'4',textColor:'#111111',bg:'#ffffff',bgOpacity:'0',bold:true,angle:'0',align:'center'};","const builtText={font:'Bahnschrift',fontSize:'4',textColor:'#111111',bg:'#ffffff',bgOpacity:'0',bold:true,italic:false,border:false,angle:'0',align:'center'};")
rep("'data-bold':d.bold?'1':'0','data-angle':d.angle||'0'","'data-bold':d.bold?'1':'0','data-italic':d.italic?'1':'0','data-border':d.border?'1':'0','data-angle':d.angle||'0'")
rep("fill:g.dataset.bg||'#fff','fill-opacity':g.dataset.bgOpacity||0,stroke:'none'","fill:g.dataset.bg||'#fff','fill-opacity':g.dataset.bgOpacity||0,stroke:g.dataset.border==='1'?(g.dataset.textColor||'#111'):'none','stroke-width':g.dataset.border==='1'?'.35':'0'")
rep("'font-weight':g.dataset.bold==='1'?'700':'400',fill:g.dataset.textColor||'#111'","'font-weight':g.dataset.bold==='1'?'700':'400','font-style':g.dataset.italic==='1'?'italic':'normal',fill:g.dataset.textColor||'#111'")
rep("$('textBold').checked=g.dataset.bold==='1';$('textAngle').value", "$('textBold').checked=g.dataset.bold==='1';$('textItalic').checked=g.dataset.italic==='1';$('textBorder').checked=g.dataset.border==='1';$('textAngle').value")
rep("$('textBold').addEventListener('change',()=>{if(selected?.dataset.type!=='text')return;selected.dataset.bold=$('textBold').checked?'1':'0';renderText(selected);drawSelection()});", "[['textBold','bold'],['textItalic','italic'],['textBorder','border']].forEach(([id,key])=>$(id).addEventListener('change',()=>{if(selected?.dataset.type!=='text')return;selected.dataset[key]=$(id).checked?'1':'0';renderText(selected);drawSelection()}));")
rep("ctx.font=`${g.dataset.bold==='1'?'700':'400'} ${fs}px ${font}`;", "ctx.font=`${g.dataset.italic==='1'?'italic ':''}${g.dataset.bold==='1'?'700':'400'} ${fs}px ${font}`;")
rep("const opa=+(g.dataset.bgOpacity||0);if(opa>0){", "const opa=+(g.dataset.bgOpacity||0);if(g.dataset.border==='1'){ctx.strokeStyle=g.dataset.textColor||'#111';ctx.lineWidth=.35;roundedRectPath(ctx,x,y,w,h,2.5);ctx.stroke()}if(opa>0){")

# Leader popup UI and CSS.
rep('#dimPopup,#textPopup{', '#dimPopup,#textPopup,#leaderPopup{')
rep('#dimPopup.open,#textPopup.open{display:block}', '#dimPopup.open,#textPopup.open,#leaderPopup.open{display:block}')
rep('</div>\n</div>\n<script>\n(()=>{', '''</div>\n</div>\n<div id="leaderPopup" aria-hidden="true" style="position:fixed;z-index:45;width:320px;background:#f7f7f8;border:1px solid #9b9ba0;border-radius:7px;box-shadow:0 14px 40px rgba(0,0,0,.24);display:none;overflow:hidden">\n <div id="leaderPopupHeader" style="height:32px;display:flex;align-items:center;padding:0 9px;background:#fff;border-bottom:1px solid #d5d5da;cursor:move;font-weight:600">Сноска <span style="flex:1"></span><button id="leaderPopupClose" class="mini">×</button></div>\n <div style="padding:9px">\n  <div class="label">Текст</div><input id="leaderText" type="text" style="width:100%">\n  <div class="row"><div style="flex:1"><div class="label">Полка, мм</div><input id="leaderShelf" type="number" min="8" max="500" step="1" value="40" style="width:100%"></div><div style="flex:1"><div class="label">Шрифт, мм</div><input id="leaderFontSize" type="number" min="1.5" max="30" step="0.5" value="4" style="width:100%"></div></div>\n  <div class="tp-checks" style="margin-top:8px"><label><input id="leaderBold" type="checkbox" checked> Жирный</label><label><input id="leaderItalic" type="checkbox"> Курсив</label></div>\n  <div class="tp-actions"><button id="leaderOk" class="primary">OK</button></div>\n </div>\n</div>\n<script>\n(()=>{''')

# Leader state.
