# setTool leader status.
rep("else if(tool==='text')setStatus('Надпись: растяните область будущего текста');else if(!tool)", "else if(tool==='text')setStatus('Надпись: растяните область будущего текста');else if(tool==='leader')setStatus('Сноска: поставьте точку стрелки и протяните к началу полки');else if(!tool)")

# Leader functions inserted before moveImageLayer.
anchor='function moveImageLayer(img,where)'
leader_js=r'''function leaderPts(g){const p1=parsePt(g.dataset.p1),p2=parsePt(g.dataset.p2),dir=(+g.dataset.dir||1),shelf=+g.dataset.shelf||40,p3={x:p2.x+dir*shelf,y:p2.y};return{p1,p2,p3,dir,shelf}}\nfunction renderLeader(g){while(g.firstChild)g.removeChild(g.firstChild);const{p1,p2,p3,dir}=leaderPts(g),c=dimDefaults.lineColor||'#111',lw=+dimDefaults.lineWidth||.4,as=+dimDefaults.arrowSize||5,aa=+dimDefaults.arrowAngle||10,sty=dimDefaults.arrow||'slim';g.appendChild(el('line',{x1:p1.x,y1:p1.y,x2:p2.x,y2:p2.y,stroke:c,'stroke-width':lw,'vector-effect':'non-scaling-stroke'}));g.appendChild(el('line',{x1:p2.x,y1:p2.y,x2:p3.x,y2:p3.y,stroke:c,'stroke-width':lw,'vector-effect':'non-scaling-stroke'}));const ux=(p2.x-p1.x)/(Math.hypot(p2.x-p1.x,p2.y-p1.y)||1),uy=(p2.y-p1.y)/(Math.hypot(p2.x-p1.x,p2.y-p1.y)||1);drawArrow(g,p1,ux,uy,as,aa,c,lw,1,sty);const fs=+g.dataset.fontSize||4,t=el('text',{x:(p2.x+p3.x)/2,y:p2.y-fs*.8,'text-anchor':'middle','dominant-baseline':'central','font-family':'Bahnschrift','font-size':fs,'font-weight':g.dataset.bold==='1'?'700':'400','font-style':g.dataset.italic==='1'?'italic':'normal',fill:c});t.textContent=g.dataset.value||'Сноска';g.appendChild(t);g.appendChild(el('path',{d:`M ${p1.x} ${p1.y} L ${p2.x} ${p2.y} L ${p3.x} ${p3.y}`,fill:'none',stroke:'transparent','stroke-width':6,class:'leader-hit'}))}\nfunction drawLeaderHandles(g){const{p1,p2,p3}=leaderPts(g);[['p1',p1],['p2',p2],['p3',p3]].forEach(([k,p])=>paper.appendChild(el('circle',{cx:p.x,cy:p.y,r:.8,class:'handle selection-ui leader-handle','data-owner':g.dataset.id,'data-leader-handle':k})))}\nfunction createLeader(p1,p2){const dir=p2.x>=p1.x?1:-1,g=el('g',{'data-type':'leader','data-id':uid++,'data-p1':`${p1.x},${p1.y}`,'data-p2':`${p2.x},${p2.y}`,'data-dir':dir,'data-shelf':'40','data-value':'Сноска','data-font-size':'4','data-bold':'1','data-italic':'0'});appendContent(g);renderLeader(g);selected=g;drawSelection();openLeaderPopup(g)}\nfunction openLeaderPopup(g){selected=g;$('leaderText').value=g.dataset.value||'';$('leaderShelf').value=g.dataset.shelf||40;$('leaderFontSize').value=g.dataset.fontSize||4;$('leaderBold').checked=g.dataset.bold==='1';$('leaderItalic').checked=g.dataset.italic==='1';const p=$('leaderPopup');p.style.display='block';p.classList.add('open');p.style.left=Math.max(10,(innerWidth-320)/2)+'px';p.style.top=Math.max(60,(innerHeight-260)/2)+'px'}\nfunction closeLeaderPopup(){const p=$('leaderPopup');p.classList.remove('open');p.style.display='none'}\n'''
rep(anchor, leader_js+anchor)

# Selection draws leader handles.
rep("if(selected.dataset.type==='image'){drawImageHandles(selected);return}}", "if(selected.dataset.type==='image'){drawImageHandles(selected);return}if(selected.dataset.type==='leader'){drawLeaderHandles(selected);return}}")

# Capture-phase leader interaction so existing handlers do not interfere.
insert="""\npaper.addEventListener('pointerdown',e=>{const p=pt(e),obj=groupType(e.target);if(tool==='leader'&&!obj){e.preventDefault();e.stopImmediatePropagation();leaderDraft={p1:p,p2:p};leaderPreview=el('path',{d:`M ${p.x} ${p.y} L ${p.x} ${p.y}`,fill:'none',stroke:'#2563eb','stroke-width':'.5','stroke-dasharray':'2 1'});paper.appendChild(leaderPreview);return}if(e.target.classList?.contains('leader-handle')){const g=findOwner(e.target.dataset.owner,'leader');if(g){selected=g;leaderDrag={obj:g,kind:e.target.dataset.leaderHandle,start:p,p1:parsePt(g.dataset.p1),p2:parsePt(g.dataset.p2),shelf:+g.dataset.shelf||40};e.preventDefault();e.stopImmediatePropagation();return}}if(obj?.dataset.type==='leader'){selected=obj;drawSelection();leaderDrag={obj,start:p,kind:'move',p1:parsePt(obj.dataset.p1),p2:parsePt(obj.dataset.p2)};e.preventDefault();e.stopImmediatePropagation()}},true);\npaper.addEventListener('pointermove',e=>{const p=pt(e);if(leaderDraft&&tool==='leader'){leaderDraft.p2=p;const dir=p.x>=leaderDraft.p1.x?1:-1,p3x=p.x+dir*40;leaderPreview.setAttribute('d',`M ${leaderDraft.p1.x} ${leaderDraft.p1.y} L ${p.x} ${p.y} L ${p3x} ${p.y}`);e.stopImmediatePropagation();return}if(!leaderDrag)return;const d=leaderDrag,g=d.obj;if(d.kind==='move'){const dx=p.x-d.start.x,dy=p.y-d.start.y;g.dataset.p1=`${d.p1.x+dx},${d.p1.y+dy}`;g.dataset.p2=`${d.p2.x+dx},${d.p2.y+dy}`}else if(d.kind==='p1')g.dataset.p1=`${p.x},${p.y}`;else if(d.kind==='p2'){g.dataset.p2=`${p.x},${p.y}`;g.dataset.dir=p.x>=parsePt(g.dataset.p1).x?'1':'-1'}else if(d.kind==='p3'){const p2=parsePt(g.dataset.p2),dir=+g.dataset.dir||1;g.dataset.shelf=String(Math.max(8,Math.abs(p.x-p2.x)));g.dataset.dir=p.x>=p2.x?'1':'-1'}renderLeader(g);drawSelection();e.stopImmediatePropagation()},true);\nwindow.addEventListener('pointerup',e=>{if(leaderDraft&&tool==='leader'){const p2=pt(e),p1=leaderDraft.p1;leaderDraft=null;leaderPreview?.remove();leaderPreview=null;if(Math.hypot(p2.x-p1.x,p2.y-p1.y)>2)createLeader(p1,p2)}leaderDrag=null},true);\npaper.addEventListener('dblclick',e=>{const obj=groupType(e.target);if(obj?.dataset.type==='leader'){e.preventDefault();e.stopImmediatePropagation();openLeaderPopup(obj)}},true);\n"""
rep("paper.addEventListener('pointerdown',e=>{const p=pt(e),obj=groupType(e.target);", insert+"paper.addEventListener('pointerdown',e=>{const p=pt(e),obj=groupType(e.target);",1)

